/* ---------- Go Vegan companion visual system ---------- */
:root {
  --bg: #f7f2e8;
  --surface: #fffdf7;
  --surface-2: #f3efe6;
  --surface-3: #e7eee5;
  --text: #111111;
  --muted: #526159;
  --border: #ded8ca;
  --primary: #123c2e;
  --primary-strong: #1a5a44;
  --primary-soft: #e3ecdf;
  --sage: #6d8b61;
  --earth: #846c52;
  --earth-soft: #f0e5d6;
  --header: rgba(255, 253, 247, .92);
  --shadow: 0 16px 48px rgba(18, 60, 46, .10);
  --shadow-sm: 0 8px 28px rgba(18, 60, 46, .07);
}

html[data-theme="dark"] {
  --bg: #1a1e1b;
  --surface: #242a26;
  --surface-2: #2d342f;
  --surface-3: #314036;
  --text: #fff;
  --muted: #b8c4b8;
  --border: #3d4a3d;
  --primary: #8fbc8f;
  --primary-strong: #a8d0a8;
  --primary-soft: #293a2e;
  --header: rgba(36, 42, 38, .94);
}

body {
  background: var(--bg);
  font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  line-height: 1.6;
}

h1, h2, h3, h4, .zerra-brand-name {
  font-family: Georgia, "Times New Roman", serif;
  letter-spacing: -.01em;
}

.content-max { max-width: 1280px; }
.zerra-content { display: block !important; }
.zerra-main { width: 100%; }

.zerra-app-header {
  border-color: var(--border);
  backdrop-filter: blur(12px) !important;
  -webkit-backdrop-filter: blur(12px);
}

.zerra-brand {
  color: var(--primary);
  text-decoration: none;
}

.zerra-brand-icon {
  font-size: 1.55rem;
  line-height: 1;
}

.zerra-brand-name {
  color: var(--text);
  font-size: 1.35rem;
  letter-spacing: -.02em;
}

.zerra-desktop-nav-item {
  position: relative;
  min-height: 2.75rem;
  border-radius: 0 !important;
  background: transparent !important;
  color: var(--muted);
}

.zerra-desktop-nav-item::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: 0;
  width: 0;
  height: 2px;
  background: var(--primary);
  transition: width .2s ease;
}

.zerra-desktop-nav-item.text-primary { color: var(--text); }
.zerra-desktop-nav-item.text-primary::after { width: 100%; }

.surface {
  border-color: var(--border);
  box-shadow: var(--shadow-sm);
}

.surface-flat { border-color: var(--border); }

.zerra-main > section > .grid {
  grid-template-columns: minmax(0, 1fr) !important;
}

.zerra-home-hero {
  display: grid;
  gap: 1.5rem;
  overflow: hidden;
  padding: 0 !important;
  border-radius: 1.5rem !important;
}

.zerra-home-hero::before,
.zerra-home-hero::after { display: none; }

.zerra-home-hero > :not(.zerra-hero-visual) {
  margin-left: 1.5rem;
  margin-right: 1.5rem;
}

.zerra-home-hero > :first-child { margin-top: 1.75rem; }
.zerra-home-hero > :last-child { margin-bottom: 1.75rem; }

.zerra-hero-title {
  color: var(--primary);
  font-weight: 700;
  line-height: 1.03;
}

html[data-theme="dark"] .zerra-hero-title {
  color: #fff;
  text-shadow: 0 3px 12px #000, 0 1px 3px #000;
}

.zerra-hero-visual {
  min-height: 15rem;
  overflow: hidden;
  background: var(--surface-2);
}

.zerra-hero-visual img {
  width: 100%;
  height: 100%;
  min-height: 15rem;
  object-fit: cover;
  object-position: 50% 47%;
  transform: scale(1.02);
}

.btn { font-weight: 700; }
.btn-primary { background: var(--primary); color: #fff; }
.input { background: var(--bg); }
.chip { background: var(--surface); }

.zerra-bottom-nav {
  background: var(--header) !important;
  backdrop-filter: blur(12px) !important;
  -webkit-backdrop-filter: blur(12px);
}

.zerra-bottom-nav-item {
  position: relative;
  transition: color .2s ease;
}

.zerra-bottom-nav-item.text-primary::after {
  content: "";
  position: absolute;
  top: 0;
  left: 28%;
  right: 28%;
  height: 2px;
  border-radius: 999px;
  background: var(--primary);
}

@media (min-width: 768px) {
  .zerra-home-hero {
    grid-template-columns: minmax(0, 1.05fr) minmax(20rem, .95fr);
    grid-template-areas:
      "copy visual"
      "search visual"
      "actions visual";
    gap: 0;
  }

  .zerra-home-hero > :nth-child(1) {
    grid-area: copy;
    margin: 0;
    padding: 3.25rem 2.25rem 1.25rem;
  }

  .zerra-home-hero > .zerra-hero-visual {
    grid-area: visual;
    min-height: 33rem;
  }

  .zerra-home-hero > :nth-child(3) {
    grid-area: search;
    margin: 0;
    padding: 0 2.25rem;
  }

  .zerra-home-hero > :nth-child(4) {
    grid-area: actions;
    margin: 0;
    padding: 1rem 2.25rem 3rem;
  }

  .zerra-hero-visual img {
    min-height: 33rem;
    object-position: 50% 50%;
  }
}

@media (min-width: 1024px) {
  .zerra-main { padding-top: 3rem; }
}

/* ---------- Approved direct-entry Today screen ---------- */
.zerra-header-actions { gap: .05rem; flex-shrink: 0; }
.zerra-header-action {
  width: 2.6rem;
  height: 2.6rem;
  flex: 0 0 2.6rem;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--primary);
  text-decoration: none;
  transition: background .18s ease, color .18s ease;
}
.zerra-header-action:hover { background: var(--surface-2); color: var(--text); }

.zerra-today-card {
  display: grid;
  grid-template-columns: minmax(0, .95fr) minmax(0, 1.05fr);
}
.zerra-today-image { width: 100%; height: 100%; min-height: 18rem; object-fit: cover; }

.zerra-life-grid { align-items: stretch; }
.zerra-life-value { min-width: 0; }
.zerra-life-icon {
  width: 4.25rem;
  height: 4.25rem;
  margin: 0 auto .65rem;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: color-mix(in srgb, var(--primary-soft) 78%, var(--earth-soft));
  color: var(--primary);
  font-size: 1.5rem;
}
.zerra-life-value { height: 100%; }

@media (max-width: 639px) {
  .zerra-app-header > div { padding-left: .75rem; padding-right: .5rem; }
  .zerra-brand { gap: .3rem; }
  .zerra-brand-icon { font-size: 1.3rem; }
  .zerra-brand-name { font-size: 1.18rem; }
  .zerra-header-action {
    width: 2.25rem;
    height: 2.25rem;
    flex-basis: 2.25rem;
  }
  .zerra-home-hero > :first-child {
    position: absolute;
    z-index: 2;
    margin: 0;
    padding: 2.2rem 1.5rem;
    max-width: 75%;
    text-shadow: 0 1px 12px rgba(255,253,247,.7);
  }
  html[data-theme="dark"] .zerra-home-hero > :first-child { color: #fff; text-shadow: none; }
  html[data-theme="dark"] .zerra-home-hero > :first-child .text-primary,
  html[data-theme="dark"] .zerra-home-hero > :first-child .text-muted { color: #fff; }
  .zerra-home-hero { position: relative; gap: 0; }
  .zerra-home-hero .zerra-hero-visual { order: -1; min-height: 26rem; }
  .zerra-home-hero .zerra-hero-visual::after {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(90deg, rgba(255,253,247,.92) 0%, rgba(255,253,247,.58) 48%, transparent 78%);
    pointer-events: none;
  }
  html[data-theme="dark"] .zerra-home-hero .zerra-hero-visual::after {
    background:
      linear-gradient(180deg, rgba(0,0,0,.42) 0%, rgba(0,0,0,.08) 55%, rgba(0,0,0,.02) 100%),
      linear-gradient(90deg, rgba(0,0,0,.9) 0%, rgba(0,0,0,.78) 52%, rgba(0,0,0,.3) 82%, rgba(0,0,0,.08) 100%);
  }
  .zerra-home-hero > :nth-child(3),
  .zerra-home-hero > :nth-child(4) { margin-left: 1rem; margin-right: 1rem; }
  .zerra-home-hero > :last-child { margin-bottom: 1.25rem; }
  .zerra-today-card { grid-template-columns: minmax(0, 1fr); }
  .zerra-today-image { min-height: 13rem; max-height: 15rem; }
  .zerra-life-section { overflow: hidden; }
  .zerra-life-grid { overflow: visible; }
  .zerra-life-value { min-width: 0; }
  .zerra-life-icon { width: 3.8rem; height: 3.8rem; }
}

@media (max-width: 390px) {
  .zerra-brand-icon { display: none; }
  .zerra-header-action { width: 2.15rem; flex-basis: 2.15rem; }
}

/* ---------- Phase 3: Reconnect ---------- */
.reconnect-hero {
  background:
    radial-gradient(circle at 92% 15%, color-mix(in srgb, var(--primary-soft) 88%, transparent), transparent 18rem),
    var(--surface);
}
.reconnect-hero h1 { color: var(--primary); max-width: 54rem; }
textarea.input { resize: vertical; }

/* ---------- Phase 4: Food, Seeds, Soil, Return & Restoration ---------- */
.food-soil-hero {
  background:
    radial-gradient(circle at 90% 12%, color-mix(in srgb, var(--earth-soft) 90%, transparent), transparent 20rem),
    var(--surface);
}
.food-soil-hero h1 { color: var(--primary); max-width: 58rem; }
.seed-outcome {
  display: inline-flex;
  min-height: 2rem;
  align-items: center;
  padding: .25rem .7rem;
  border-radius: 999px;
  background: var(--primary-soft);
  color: var(--primary);
  border: 1px solid color-mix(in srgb, var(--primary) 25%, var(--border));
  font-size: .72rem;
  font-weight: 800;
  text-transform: capitalize;
  white-space: nowrap;
}
.seed-outcome-warn {
  background: var(--earth-soft);
  color: var(--earth);
  border-color: color-mix(in srgb, var(--earth) 30%, var(--border));
}
